import hashlib, ssl
from tls_parse import parse_client_hello     # reads the fields out of the bytes (not shown)

GREASE = {0x0a0a + 0x1010 * i for i in range(16)}   # 0x0a0a ... 0xfafa, reserved by RFC 8701

def client_hello_bytes(server_name="example.com"):
    ctx = ssl.create_default_context()
    ctx.set_alpn_protocols(["h2", "http/1.1"])
    out = ssl.MemoryBIO()
    tls = ctx.wrap_bio(ssl.MemoryBIO(), out, server_hostname=server_name)
    try:
        tls.do_handshake()            # writes a real ClientHello into 'out', then waits
    except ssl.SSLWantReadError:
        pass                          # for a ServerHello that never comes: no network used
    return out.read()

def ja3(h):
    f = lambda xs: "-".join(str(x) for x in xs if x not in GREASE)
    s = f"{h['version']},{f(h['ciphers'])},{f(h['exts'])},{f(h['groups'])},{f(h['formats'])}"
    return s, hashlib.md5(s.encode()).hexdigest()

print(ssl.OPENSSL_VERSION)
s, digest = ja3(parse_client_hello(client_hello_bytes()))
print(s)
print(digest)
